import {test} from 'node:test';import assert from 'node:assert/strict';
import {createPoseOwnership} from '../simulation/pose-ownership.mjs';
test('one owner preserves intent, rejects duplicate events and holds unsafe releases',()=>{let safe=false,events=0;const owner=createPoseOwnership({capture:()=>({phase:'delivery',cargo:3}),recover:(id,p,e)=>safe&&e.previous.cargo===3,describe:()=>events++});owner.acquire(['a'],{mode:'carry-on'});owner.acquire(['a'],{mode:'panic'});assert.equal(owner.snapshot().held[0][1].mode,'carry-on');assert.equal(owner.release('a',{}),false);assert.ok(owner.owns('a'));owner.event({sequence:2,bodyId:'a',type:'contact'});owner.event({sequence:2,bodyId:'a',type:'contact'});assert.equal(events,1);safe=true;assert.ok(owner.release('a',{}));assert.ok(!owner.owns('a'));});
test('ownership and event order survive restore',()=>{const make=()=>createPoseOwnership({capture:()=>({phase:'walking'}),recover:()=>true,describe:()=>{}});const a=make();a.acquire(['a']);a.event({sequence:4});const b=make();b.restore(JSON.parse(JSON.stringify(a.snapshot())));assert.ok(b.owns('a'));assert.equal(b.event({sequence:3}),false);b.clear();assert.ok(!b.owns('a'));});
